241→// parseHookType parses a specific hook type from rawHooks into the target slice.
242→// Silently ignores parse errors (leaves target unchanged).
243→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]FactoryHookMatcher) {
244→	if data, ok := rawHooks[hookType]; ok {
245→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
246→		json.Unmarshal(data, target)
247→	}
248→}
249→
250→// marshalHookType marshals a hook type back to rawHooks.
251→// If the slice is empty, removes the key from rawHooks.
252→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
253→	if len(matchers) == 0 {
254→		delete(rawHooks, hookType)
255→		return
256→	}
257→	data, err := json.Marshal(matchers)
258→	if err != nil {
259→		return // Silently ignore marshal errors (shouldn't happen)
260→	}
261→	rawHooks[hookType] = data
262→}
