188→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
189→// This is used for rewind operations to restore transcript state.
190→// Requires NativeData to be populated.
191→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
192→	if session == nil {
193→		return nil, errors.New("session is nil")
194→	}
195→
196→	if len(session.NativeData) == 0 {
197→		return nil, errors.New("session has no native data")
198→	}
199→
200→	if uuid == "" {
201→		// No truncation needed, return copy
202→		return &agent.AgentSession{
203→			SessionID:     session.SessionID,
204→			AgentName:     session.AgentName,
205→			RepoPath:      session.RepoPath,
206→			SessionRef:    session.SessionRef,
207→			StartTime:     session.StartTime,
208→			NativeData:    session.NativeData,
209→			ModifiedFiles: session.ModifiedFiles,
210→		}, nil
211→	}
212→
213→	// Parse, truncate, re-serialize
214→	lines, err := transcript.ParseFromBytes(session.NativeData)
215→	if err != nil {
216→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
217→	}
218→
219→	truncated := TruncateAtUUID(lines, uuid)
220→
221→	newData, err := SerializeTranscript(truncated)
222→	if err != nil {
223→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
224→	}
225→
226→	return &agent.AgentSession{
227→		SessionID:     session.SessionID,
228→		AgentName:     session.AgentName,
229→		RepoPath:      session.RepoPath,
230→		SessionRef:    session.SessionRef,
231→		StartTime:     session.StartTime,
232→		NativeData:    newData,
233→		ModifiedFiles: ExtractModifiedFiles(truncated),
234→	}, nil
235→}
