// WriteHookResponse outputs the hook response as plain text to stderr.
// Factory AI Droid does not parse JSON hook responses from stdout,
// so we write directly to stderr to display the message in the terminal.
func (f *FactoryAIDroidAgent) WriteHookResponse(message string) error {
